import pandas as pd

def load() -> pd.DataFrame:
    path = 'data/astronomy/input/omni2_low_res/omni2.txt'
    with open(path, 'r', encoding='utf-8', errors='ignore') as f:
        txt = f.read()
    return pd.DataFrame([{'path': path, 'content': txt}])

def load() -> pd.DataFrame:
    import glob, pandas as pd
    files = sorted(glob.glob('data/astronomy/input/swarmb/SB_DNS_POD_2024_*.txt'))
    return pd.DataFrame({'path': files})

def process(nrlmsise_rho) -> pd.DataFrame:
    import numpy as np
    df = nrlmsise_rho.dropna(subset=['rho_meas','rho_model']).copy()
    err = df['rho_model'].to_numpy() - df['rho_meas'].to_numpy()
    rmse = float(np.sqrt(np.mean(err**2)))
    return pd.DataFrame({'rmse':[rmse]})
